export let itaTournamentsAsOf = globalThis.__BAGEL_REMOTE__?.["itaTournaments"]?.itaTournamentsAsOf ?? "2026-10-19";

export function getItaTournaments({ activeWindowDays = 30 } = {}) {
  const cutoff = new Date(Date.now() - activeWindowDays * 86400e3).toISOString().slice(0, 10);
  return itaTournaments.filter((e) => e.end >= cutoff);
}

// §465 in-place swap (generated by apply-remote-overrides)
export function __bagelSwap(ns) {
  if (ns && ns.itaTournaments !== undefined) itaTournaments = ns.itaTournaments;
  if (ns && ns.itaTournamentsAsOf !== undefined) itaTournamentsAsOf = ns.itaTournamentsAsOf;
}
